import { get, handleApiError, post } from '@helpers/httpClient';

import {
  mapFullRecipeToFront,
  mapRecipeCategoryToFront,
  mapRecipeGroupToFront,
  mapRecipeStructureProductsToFront,
  mapRecipeUsagesToFront,
} from '../@mappers/recipes.mapper';
import {
  IAddRecipeDTO,
  IAddRecipeResultDTO,
  IFullRecipeDTO,
  IRecipeCriteriaDTO,
  IRecipesCategoryDTO,
  IRecipesGroupsDTO,
  IRecipeStructureProductAddDTO,
  IRecipeStructureProductAddResultDTO,
  IRecipeStructureProductDeleteDTO,
  IRecipeStructureProductDTO,
  IRecipeStructureProductUpdateDTO,
  IRecipeUsagesDTO,
  IUpdateRecipeDTO,
} from '../@types/recipes.backTypes';
import {
  IBaseRecipe,
  IFullRecipe,
  IRecipeCategory,
  IRecipesGroup,
  IRecipeStructureProduct,
} from '../@types/recipes.types';

export const getRecipesWithCategories = async (
  opts: IRecipeCriteriaDTO = {},
): Promise<IRecipesGroup[]> => {
  const rawData = await get<IRecipesGroupsDTO[], IRecipeCriteriaDTO>(
    '/ajax/recipes/recipes_get_all.php',
    opts,
  );
  return rawData.map(mapRecipeGroupToFront);
};

export const getRecipeByIdAsync = async (id: number): Promise<IFullRecipe> => {
  try {
    const recipe = await get<IFullRecipeDTO>('/ajax/recipes/recipe_one.php', {
      id,
    }).then<IFullRecipeDTO>(handleApiError);

    return mapFullRecipeToFront(recipe);
  } catch (e) {
    return Promise.reject((e as Error).message);
  }
};

export const getRecipeCategories = async (): Promise<IRecipeCategory[]> => {
  const rawData = await get<IRecipesCategoryDTO[]>('/ajax/recipes/recipes_get_categories.php');
  return rawData.map(mapRecipeCategoryToFront);
};

export const addRecipeAsync = async (data: IAddRecipeDTO): Promise<IBaseRecipe> => {
  const res = await post<IAddRecipeResultDTO, IAddRecipeDTO>(
    '/ajax/recipes/recipes_add.php',
    data,
  ).then<IAddRecipeResultDTO>(handleApiError);

  return {
    id: +res.id,
    name: data.name_recipe,
    promo: data.promo_text,
    water_count: data.water_count ? +data.water_count : null,
    gas_count: data.gas_count ? data.gas_count : null,
    cooking_time: data.cooking_time ? +data.cooking_time : null,
    photo: data.photo ?? '',
    id_author: res.id_author,
    text: data.text,
  };
};
export const updateRecipeAsync = async (data: IUpdateRecipeDTO): Promise<boolean> => {
  const res = await post<{ success: boolean }, IUpdateRecipeDTO>(
    '/ajax/recipes/recipe_edit.php',
    data,
  ).then(handleApiError);

  return res.success;
};

export const getRecipeStructureProducts = async (
  id_recipe: number,
): Promise<IRecipeStructureProduct[]> => {
  const res = await get<IRecipeStructureProductDTO[]>('/ajax/recipes/recipes_products.php', {
    id: id_recipe,
  }).then(handleApiError);

  return res.map(mapRecipeStructureProductsToFront);
};

export const addRecipeStructureProduct = async (
  id_recipe: number,
  id_product: number,
): Promise<number> => {
  const res = await post<IRecipeStructureProductAddResultDTO, IRecipeStructureProductAddDTO>(
    '/ajax/recipes/recipes_product_add.php',
    { id_product, id_recipe },
  ).then<IRecipeStructureProductAddResultDTO>(handleApiError);

  return res.id;
};

export const updateRecipeStructureProduct = async (
  id_recipe_structure: number,
  amount: number,
): Promise<boolean> => {
  const res = await post<IRecipeStructureProductAddResultDTO, IRecipeStructureProductUpdateDTO>(
    '/ajax/recipes/recipes_product_edit.php',
    { id: id_recipe_structure, amount },
  ).then<IRecipeStructureProductAddResultDTO>(handleApiError);

  return res.success;
};

export const deleteRecipeStructureProduct = async (
  id_recipe_structure: number,
): Promise<boolean> => {
  const res = await post<{ success: boolean }, IRecipeStructureProductDeleteDTO>(
    '/ajax/recipes/recipes_product_del.php',
    { id: id_recipe_structure },
  ).then(handleApiError);

  return res.success;
};

export const getRecipeUsagesByIdAsync = async (id_recipe: number) => {
  const res = await get<IFullRecipeDTO>('/ajax/recipes/recipe_usages.php', {
    id_recipe,
  }).then<IRecipeUsagesDTO>(handleApiError);

  return mapRecipeUsagesToFront(res);
};
